const DAY_MS = 24 * 60 * 60 * 1000;

class TokenBudget {
  constructor({ dailyLimits = {}, defaultLimit = 0, clock }) {
    this.dailyLimits = dailyLimits;
    this.defaultLimit = defaultLimit;
    this.clock = clock;
    this.usage = new Map();         // 'tenant|day' -> { used, reserved }
    this.reservations = new Map();  // id -> { key, tokens }
    this.nextId = 1;
  }

  limitFor(tenant) {
    return tenant in this.dailyLimits ? this.dailyLimits[tenant] : this.defaultLimit;
  }

  bucket(tenant) {
    const key = tenant + '|' + Math.floor(this.clock.now() / DAY_MS); // UTC day
    if (!this.usage.has(key)) this.usage.set(key, { used: 0, reserved: 0 });
    return { key, b: this.usage.get(key) };
  }

  remaining(tenant) {
    const { b } = this.bucket(tenant);
    return Math.max(0, this.limitFor(tenant) - b.used - b.reserved);
  }

  reserve(tenant, estimatedTokens) {
    const left = this.remaining(tenant);
    if (estimatedTokens > left) return { ok: false, reason: 'over_budget', remaining: left };
    const { key, b } = this.bucket(tenant);
    b.reserved += estimatedTokens;
    const id = 'r' + this.nextId++;
    this.reservations.set(id, { key, tokens: estimatedTokens });
    return { ok: true, id };
  }

  settle(id, actualTokens) {
    const r = this.reservations.get(id);
    if (!r) return false; // unknown or already settled/released: idempotent no-op
    this.reservations.delete(id);
    const b = this.usage.get(r.key);
    b.reserved -= r.tokens;
    b.used += actualTokens;
    return true;
  }

  release(id) {
    return this.settle(id, 0);
  }
}

