let t = Date.UTC(2026, 8, 1, 14, 0); const clock = { now: () => t };
const budget = new TokenBudget({ dailyLimits: { lincoln: 10000, oakwood: 2000 }, defaultLimit: 500, clock });
const r = budget.reserve('lincoln', 4000);
assertEqual(r, { ok: true, id: 'r1' });
assertEqual(budget.remaining('lincoln'), 6000);
budget.settle('r1', 1500);
assertEqual(budget.remaining('lincoln'), 8500);

let t = Date.UTC(2026, 8, 1, 14, 0); const clock = { now: () => t };
const budget = new TokenBudget({ dailyLimits: { lincoln: 10000, oakwood: 2000 }, defaultLimit: 500, clock });
assertEqual(budget.reserve('lincoln', 6000).ok, true);
const second = budget.reserve('lincoln', 6000);
assertEqual(second, { ok: false, reason: 'over_budget', remaining: 4000 });
assertEqual(budget.remaining('lincoln'), 4000, 'a rejected reserve must hold nothing');
assertEqual(budget.reserve('lincoln', 4000).ok, true, 'exactly the remaining amount fits');
assertEqual(budget.remaining('lincoln'), 0);

